\section{Introduction}

\subsection{The problem}
Fix $M\ge 2$ and a primitive $M$-th root of unity $\zeta$ in a field of characteristic zero. The discrete Fourier transform matrix of order $M$ is
\[
F_M=\big(\zeta^{jk}\big)_{j,k=0}^{M-1}.
\]
Given $n$-element subsets $A=\{a_1,\dots,a_n\}$ and $B=\{b_1,\dots,b_n\}$ of $\ZM$, write $F_M[A,B]=\big(\zeta^{a_ib_j}\big)_{i,j=1}^n$ for the corresponding minor. For which $M$ is $F_M[A,B]$ nonsingular for \emph{all} $A$, $B$? Chebotarev proved in 1926 that primality suffices; we prove below that it is also necessary.

\subsection{Why it matters}
Nonsingularity of \emph{all} minors is exactly the hypothesis behind a family of ``no exceptions'' statements: exact reconstruction of a signal supported in $A$ from its Fourier data on \emph{any} equally large frequency set; an uncertainty principle strictly stronger than the general bound $\#\supp f\cdot\#\supp\hf\ge|G|$; and a Fourier route to the Cauchy--Davenport inequality of additive combinatorics.

\subsection{Notation}
$\binom{m}{k}=0$ for $k>m$. For $f:\Zp\to\mathbb{C}$ set $\supp f=\{x: f(x)\ne0\}$ and
\[
\hf(t)=\sum_{x\in\Zp}\omega^{xt}f(x),\qquad \omega=e^{-2\pi i/p},
\]
and $(f*g)(x)=\sum_y f(y)g(x-y)$. The \emph{staircase number} is $N(n)=0+1+\cdots+(n-1)=\binom{n}{2}$, and $V(c)=\det\big(c_i^{\,k}\big)_{i=1..n,\,k=0..n-1}=\prod_{i<j}(c_j-c_i)$ is the Vandermonde determinant.

\section{Chebotarev's theorem}

\begin{theorem}[Chebotarev]\label{thm:cheb}
Let $p$ be prime, $K$ a field of characteristic zero and $\zeta\in K$ a primitive $p$-th root of unity. Let $a_1,\dots,a_n$ and $b_1,\dots,b_n$ be pairwise distinct elements of $\{0,1,\dots,p-1\}$. Then
\[
\det\big(\zeta^{\,a_ib_j}\big)_{i,j=1}^n\ \ne\ 0 .
\]
\end{theorem}

Set
\[
P(X)=\det\big((1+X)^{a_ib_j}\big)_{i,j=1}^n\in\mathbb{Z}[X],\qquad s_i=(1+X)^{a_i}-1 .
\]

\begin{lemma}[Shift lemma]\label{lem:shift}
For every $m\ge0$ there is $w_m\in\mathbb{Z}[X]$ with $(1+X)^m-1=X\,w_m$ and $w_m(0)=m$.
\end{lemma}

\begin{proof}
Induct on $m$, using $(1+X)^{m+1}-1=(1+X)\big((1+X)^m-1\big)+X$, so $w_{m+1}=(1+X)w_m+1$ and $w_{m+1}(0)=w_m(0)+1$.
\end{proof}

\begin{lemma}[Uniform binomial expansion]\label{lem:binom}
If $m<p$ then, in any commutative ring, $(1+s)^m=\sum_{k=0}^{p-1}\binom{m}{k}s^k$.
\end{lemma}

\begin{proof}
The binomial theorem gives the terms $k\le m$; the remaining terms vanish since $\binom{m}{k}=0$ for $k>m$. The point is the \emph{uniform} index range $\{0,\dots,p-1\}$, independent of $m$.
\end{proof}

\begin{lemma}[Multilinear determinant expansion]\label{lem:multilin}
Let $R$ be a commutative ring, $c:\{1..n\}\times\{1..m\}\to R$ and $E:\{1..m\}\times\{1..n\}\to R$. Then
\[
\det\Big(\sum_{k=1}^m c_{ik}E_{kj}\Big)_{i,j}=\sum_{f:\{1..n\}\to\{1..m\}}\Big(\prod_{i=1}^n c_{i,f(i)}\Big)\det\big(E_{f(i),j}\big)_{i,j}.
\]
\end{lemma}

\begin{proof}
The determinant is alternating and multilinear in the rows; expand each row as a sum over $k$, obtaining one term per choice function $f$, then pull the scalar $c_{i,f(i)}$ out of row $i$.
\end{proof}

\begin{proposition}[Expansion of $P$]\label{prop:expansion}
If $b_j<p$ for all $j$, then
\[
P(X)=\sum_{f:\{1..n\}\to\{0,\dots,p-1\}}\Big(\prod_{i=1}^n s_i^{\,f(i)}\Big)\det\Big(\binom{b_j}{f(i)}\Big)_{i,j}.
\]
\end{proposition}

\begin{proof}
Write $(1+X)^{a_ib_j}=(1+s_i)^{b_j}$ and expand each entry by Lemma~\ref{lem:binom}; then apply Lemma~\ref{lem:multilin} with $c_{ik}=s_i^{\,k}$ and $E_{kj}=\binom{b_j}{k}$.
\end{proof}

\begin{lemma}\label{lem:noninj}
If $f$ is not injective then $\det\big(\binom{b_j}{f(i)}\big)_{i,j}=0$.
\end{lemma}

\begin{proof}
Two rows coincide.
\end{proof}

\begin{lemma}[Staircase bound]\label{lem:stair}
If $f:\{1..n\}\to\mathbb{Z}_{\ge0}$ is injective then $\sum_i f(i)\ge N(n)$, with equality only if $f$ is a bijection onto $\{0,1,\dots,n-1\}$.
\end{lemma}

\begin{proof}
The image consists of $n$ distinct nonnegative integers; the $j$-th smallest is $\ge j-1$. If some value were $\ge n$, deleting it and applying the bound to the remaining $n-1$ values gives $\sum_i f(i)\ge N(n-1)+n>N(n)$.
\end{proof}

\begin{theorem}\label{thm:order}
$X^{N(n)}\mid P(X)$ in $\mathbb{Z}[X]$.
\end{theorem}

\begin{proof}
By Proposition~\ref{prop:expansion} and Lemma~\ref{lem:noninj}, only injective $f$ contribute. For such $f$, Lemma~\ref{lem:shift} gives $s_i^{f(i)}=X^{f(i)}w_{a_i}^{f(i)}$, so the term is divisible by $X^{\sum_if(i)}$, and $\sum_i f(i)\ge N(n)$ by Lemma~\ref{lem:stair}.
\end{proof}

\begin{theorem}[Staircase coefficient]\label{thm:coeff}
Let $\chi(b)=\det\big(\binom{b_i}{k}\big)_{i=1..n,\,k=0..n-1}$. Then
\[
[X^{N(n)}]\,P \;=\; V(a)\cdot\chi(b),\qquad V(a)=\prod_{i<j}(a_j-a_i).
\]
\end{theorem}

\begin{proof}
Each injective term factors as $X^{\sum_i f(i)}U_f(X)$ with $U_f(0)=\big(\prod_i a_i^{f(i)}\big)\det\big(\binom{b_j}{f(i)}\big)$, by Lemma~\ref{lem:shift}. Terms with $\sum_i f(i)>N(n)$ do not contribute to $[X^{N(n)}]P$, and by Lemma~\ref{lem:stair} those with $\sum_i f(i)=N(n)$ are exactly the bijections onto $\{0,\dots,n-1\}$. Hence
\[
[X^{N(n)}]P=\sum_{g:\{1..n\}\to\{0,\dots,n-1\}}\Big(\prod_i a_i^{\,g(i)}\Big)\det\Big(\binom{b_j}{g(i)}\Big)_{i,j},
\]
the non-injective $g$ contributing zero. Applying Lemma~\ref{lem:multilin} in reverse identifies this with $\det\big(\sum_{k}a_i^{\,k}\binom{b_j}{k}\big)_{i,j}$, the determinant of the product of the Vandermonde matrix $(a_i^{\,k})$ with the binomial matrix $(\binom{b_j}{k})$; the result is $V(a)\chi(b)$.
\end{proof}

\begin{lemma}[Superfactorial identity]\label{lem:superfact}
$\Big(\prod_{k=0}^{n-1}k!\Big)\chi(b)=V(b)=\prod_{i<j}(b_j-b_i)$.
\end{lemma}

\begin{proof}
The falling factorials $\mathrm{fall}_k(Y)=Y(Y-1)\cdots(Y-k+1)$ are monic of degree $k$; for any such family $\det\big(\mathrm{fall}_k(b_i)\big)=V(b)$, since the change of basis from $\{Y^k\}$ is unipotent triangular. Now $\mathrm{fall}_k(b_i)=k!\binom{b_i}{k}$; factor $k!$ out of column $k$.
\end{proof}

\begin{corollary}\label{cor:prime}
If the $a_i$ are distinct elements of $\{0,\dots,p-1\}$ and likewise the $b_j$, then $p\nmid V(a)$, $p\nmid\chi(b)$ and hence $p\nmid[X^{N(n)}]P$. In particular $P$ vanishes at the origin to order exactly $N(n)$.
\end{corollary}

\begin{proof}
$V(a)$ is a product of nonzero integers of absolute value $<p$, hence prime to $p$; likewise $V(b)$. If $p\mid\chi(b)$ then $p\mid V(b)$ by Lemma~\ref{lem:superfact}, a contradiction.
\end{proof}

\begin{lemma}[Shifted cyclotomic polynomial]\label{lem:shiftcyc}
Let $\Phi_p(X)=1+X+\cdots+X^{p-1}$ and $\Psi_p(X)=\Phi_p(X+1)$. Then $X\Psi_p(X)=(1+X)^p-1$ and therefore $[X^k]\Psi_p=\binom{p}{k+1}$ for $0\le k\le p-1$. In particular $\Psi_p(0)=p$, all coefficients of degree $<p-1$ are divisible by $p$, and the leading coefficient is $1$.
\end{lemma}

\begin{proof}
Substitute $Y=X+1$ into $(Y-1)\Phi_p(Y)=Y^p-1$ and expand by the binomial theorem.
\end{proof}

\begin{proposition}[Divisibility step]\label{prop:div}
Let $P\in\mathbb{Z}[X]$ have $[X^m]P=0$ for all $m<N$, and suppose $\Psi_p\mid P$. Then $p\mid[X^N]P$.
\end{proposition}

\begin{proof}
Write $P=\Psi_pQ$. By strong induction on $m$ we show $[X^m]Q=0$ whenever $m+(p-1)\le N$: in $[X^m](\Psi_pQ)=\sum_{k+\ell=m}[X^k]\Psi_p[X^\ell]Q$ all terms with $\ell<m$ vanish by induction, leaving $p\,[X^m]Q=[X^m]P=0$, so $[X^m]Q=0$. Now, in $[X^N]P=\sum_{k+\ell=N}[X^k]\Psi_p[X^\ell]Q$, either $k+1<p$ and $p\mid\binom{p}{k+1}$, or $k\ge p-1$ and then $\ell+(p-1)\le N$ so $[X^\ell]Q=0$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:cheb}]
Suppose $\det(\zeta^{a_ib_j})=0$. Substituting $X=\zeta-1$ into $P$ gives exactly this determinant, so $\zeta-1$ is a root of $P$; equivalently $\zeta$ is a root of $P(X-1)$. As $\zeta$ is an algebraic integer with minimal polynomial $\Phi_p$ (irreducible, monic, integral), $\Phi_p\mid P(X-1)$ in $\mathbb{Z}[X]$, whence $\Psi_p\mid P$. By Theorem~\ref{thm:order} all coefficients of $P$ below degree $N(n)$ vanish, so Proposition~\ref{prop:div} gives $p\mid[X^{N(n)}]P$, contradicting Corollary~\ref{cor:prime}.
\end{proof}

\begin{theorem}[Rectangular form: full row rank]\label{thm:rect}
Let $p$ be prime, $\zeta$ a primitive $p$-th root of unity in a characteristic-zero field $K$, and $n\le m$. Let $a_1,\dots,a_n$ and $b_1,\dots,b_m$ be distinct residues mod $p$. If $v\in K^n$ satisfies $\sum_{i=1}^n v_i\zeta^{a_ib_j}=0$ for $j=1,\dots,m$, then $v=0$.
\end{theorem}

\begin{proof}
Restrict to the first $n$ columns; the square minor is invertible by Theorem~\ref{thm:cheb}, so its left kernel is trivial.
\end{proof}

\begin{theorem}[Converse: primality is necessary]\label{thm:converse}
Let $M>1$ be composite and $\zeta$ a primitive $M$-th root of unity in a field. Then there exist distinct residues $a_1\ne a_2$ and $b_1\ne b_2$ modulo $M$ with $\det\big(\zeta^{a_ib_j}\big)_{i,j=1}^2=0$. Hence, for $M>1$, all square submatrices of $F_M$ are nonsingular if and only if $M$ is prime.
\end{theorem}

\begin{proof}
Write $M=de$ with $1<d<M$, so $2\le e<M$. Take $a=(0,e)$, $b=(0,d)$. Since $\zeta^{ed}=\zeta^M=1$, all four entries equal $1$ and the determinant vanishes. The equivalence follows with Theorem~\ref{thm:cheb}.
\end{proof}

The smallest instance is $M=4$, $\zeta=i$, $a=b=(0,2)$.

\section{The prime-order uncertainty principle}

\begin{theorem}[Uncertainty principle]\label{thm:unc}
Let $p$ be prime and $f:\Zp\to\mathbb{C}$ nonzero. Then
\[
\#\supp f+\#\supp\hf\ \ge\ p+1 .
\]
\end{theorem}

\begin{proof}
Let $A=\supp f$ and $k=\#A\ge1$. If $\#\supp\hf\le p-k$, the complement of $\supp\hf$ has at least $k$ elements; choose $B$ with $\#B=k$ and $\hf|_B=0$. Enumerating $A=\{\alpha_i\}$, $B=\{\beta_j\}$ and putting $v_i=f(\alpha_i)$ we get $\sum_i v_i\omega^{\alpha_i\beta_j}=\hf(\beta_j)=0$ for all $j$. Thus $v$ lies in the left kernel of the minor $(\omega^{\alpha_i\beta_j})$, nonsingular by Theorem~\ref{thm:cheb}; so $v=0$, contradicting $f(\alpha_1)\ne0$.
\end{proof}

\begin{remark}
The bound $\#\supp f\cdot\#\supp\hf\ge|G|$ holds for every finite abelian group; Theorem~\ref{thm:unc} is a genuinely prime-order phenomenon and is much stronger for small supports.
\end{remark}

\begin{proposition}[Dirac case]\label{prop:dirac}
For $\delta_0(x)=\mathbf 1[x=0]$ we have $\widehat{\delta_0}\equiv1$, so $\#\supp\delta_0+\#\supp\widehat{\delta_0}=1+p=p+1$.
\end{proposition}

\begin{lemma}[Extremal construction]\label{lem:extremal}
Let $A,S\subseteq\Zp$ with $\#A=\#S+1$. Then there is a nonzero $f$ vanishing off $A$ with $\hf|_S=0$.
\end{lemma}

\begin{proof}
The linear map sending a function supported in $A$ (dimension $\#A$) to its Fourier data on $S$ (dimension $\#A-1$) has nontrivial kernel. Concretely, padding the evaluation matrix with a zero column produces a square matrix of determinant $0$, which therefore admits a nonzero annihilating vector.
\end{proof}

\begin{theorem}[Sharpness on every support]\label{thm:sharp}
Let $p$ be prime and $\emptyset\ne A\subseteq\Zp$. Then there is $f$ with $\supp f=A$ exactly and $\#\supp f+\#\supp\hf=p+1$.
\end{theorem}

\begin{proof}
Pick any $S$ with $\#S=\#A-1$ and let $f$ be as in Lemma~\ref{lem:extremal}. Then $\#\supp f\le\#A$ and $\#\supp\hf\le p-(\#A-1)$, so the sum is at most $p+1$; Theorem~\ref{thm:unc} forces equality, hence $\supp f=A$.
\end{proof}

\begin{theorem}[Rigidity of extremal kernels]\label{thm:rigid}
Let $p$ be prime and $A,S\subseteq\Zp$ with $\#A=\#S+1$. Then
\[
\mathcal K(A,S)=\{f:\supp f\subseteq A,\ \hf|_S=0\}
\]
is exactly one-dimensional.
\end{theorem}

\begin{proof}
Existence of a nonzero element is Lemma~\ref{lem:extremal}. Let $f\ne0$ in $\mathcal K(A,S)$, choose $a_0$ with $f(a_0)\ne0$, let $g\in\mathcal K(A,S)$, set $c=g(a_0)/f(a_0)$ and $h=g-cf\in\mathcal K(A,S)$. Then $h(a_0)=0$, so $\#\supp h\le\#A-1=\#S$, while $\#\supp\hat h\le p-\#S$. If $h\ne0$ this contradicts Theorem~\ref{thm:unc}. Hence $g=cf$.
\end{proof}

\section{Exact sparse recovery}

Call $f$ \emph{$k$-sparse} if $\#\supp f\le k$.

\begin{theorem}[Recovery from any $2k$ frequencies]\label{thm:recovery}
Let $p$ be prime and $S\subseteq\Zp$ with $\#S\ge2k$. If $f,g$ are $k$-sparse and $\hf|_S=\widehat g|_S$, then $f=g$.
\end{theorem}

\begin{proof}
Let $h=f-g$. Then $\#\supp h\le2k$ and $\widehat h|_S=0$, so $\#\supp\widehat h\le p-2k$. If $h\ne0$, Theorem~\ref{thm:unc} gives $p+1\le 2k+(p-2k)=p$, absurd.
\end{proof}

\begin{remark}
The measurement set $S$ is arbitrary: an adversary may choose which $2k$ Fourier coefficients are revealed and uniqueness still holds. There is no randomness, no restricted isometry hypothesis, and no failure probability.
\end{remark}

\begin{theorem}[Optimality of the threshold]\label{thm:optimal}
Let $1\le k$ and $2k\le p$, and let $S\subseteq\Zp$ with $\#S=2k-1$. Then there exist distinct $k$-sparse $f,g$ with $\hf|_S=\widehat g|_S$.
\end{theorem}

\begin{proof}
Choose $A$ with $\#A=2k=\#S+1$ and let $h\ne0$ be supported in $A$ with $\widehat h|_S=0$ (Lemma~\ref{lem:extremal}). Split $A=A_1\sqcup A_2$ with $\#A_1=\#A_2=k$ and put $f=h\mathbf 1_{A_1}$, $g=-h\mathbf 1_{A_2}$. Both are $k$-sparse, $f-g=h\ne0$, and $\hf-\widehat g=\widehat h$ vanishes on $S$.
\end{proof}

\section{Cauchy--Davenport via convolution}

\begin{lemma}[Convolution theorem]\label{lem:conv}
$\widehat{f*g}(t)=\hf(t)\widehat g(t)$ for all $t$.
\end{lemma}

\begin{proof}
Expand and substitute $x=y+z$; the character identity $\omega^{(y+z)t}=\omega^{yt}\omega^{zt}$ factors the double sum.
\end{proof}

\begin{lemma}\label{lem:suppconv}
$\supp(f*g)\subseteq\supp f+\supp g$.
\end{lemma}

\begin{proof}
If $(f*g)(x)\ne0$ some summand $f(y)g(x-y)$ is nonzero, and $x=y+(x-y)$.
\end{proof}

\begin{lemma}[Pigeonhole]\label{lem:pigeon}
If $X,Y\subseteq\Zp$ with $\#X+\#Y>p$ then $X\cap Y\ne\emptyset$.
\end{lemma}

\begin{proof}
$\#X+\#Y=\#(X\cap Y)+\#(X\cup Y)\le\#(X\cap Y)+p$.
\end{proof}

\begin{theorem}[Cauchy--Davenport]\label{thm:cd}
Let $p$ be prime and $A,B\subseteq\Zp$ nonempty. Then
\[
\#(A+B)\ \ge\ \min\big(p,\ \#A+\#B-1\big).
\]
\end{theorem}

\begin{proof}
Write $\alpha=\#A$, $\beta=\#B$.

\emph{Case 1: $\alpha+\beta>p+1$.} For any $x$ the set $x-B$ has $\beta$ elements and $\alpha+\beta>p$, so by Lemma~\ref{lem:pigeon} there is $a\in A\cap(x-B)$, i.e. $x\in A+B$. Hence $A+B=\Zp$.

\emph{Case 2: $\alpha+\beta\le p+1$.} Choose $T\subseteq\Zp$ with $\#T=\alpha+\beta-2$ and split $T=S_A\sqcup S_B$ with $\#S_A=\alpha-1$, $\#S_B=\beta-1$. By Lemma~\ref{lem:extremal} choose nonzero $f$ supported in $A$ with $\hf|_{S_A}=0$, and nonzero $g$ supported in $B$ with $\widehat g|_{S_B}=0$. By Theorem~\ref{thm:unc}, $\#\supp\hf\ge p+1-\alpha$ and $\#\supp\widehat g\ge p+1-\beta$, and these sum to $2p+2-\alpha-\beta\ge p+1>p$; so by Lemma~\ref{lem:pigeon} some $t$ has $\hf(t)\widehat g(t)\ne0$, whence $h:=f*g\ne0$ by Lemma~\ref{lem:conv}. Also $\widehat h=\hf\widehat g$ vanishes on $T$, so $\#\supp\widehat h\le p-(\alpha+\beta-2)$, while $\supp h\subseteq A+B$ by Lemma~\ref{lem:suppconv}. Theorem~\ref{thm:unc} applied to $h$ gives
\[
p+1\ \le\ \#(A+B)+p-\alpha-\beta+2,
\]
i.e. $\#(A+B)\ge\alpha+\beta-1$.
\end{proof}

\section{Algorithms}

\subsection{The staircase coefficient}
Given distinct residues $a_i,b_j$ mod $p$, Theorem~\ref{thm:coeff} and Lemma~\ref{lem:superfact} give
\[
[X^{N(n)}]P=V(a)\chi(b),\qquad V(a)=\prod_{i<j}(a_j-a_i),\quad \chi(b)=\frac{\prod_{i<j}(b_j-b_i)}{\prod_{k=0}^{n-1}k!},
\]
computable in $O(n^2)$ integer multiplications. Its nonvanishing mod $p$ is an exact certificate of nonsingularity of the corresponding DFT minor, replacing an ill-conditioned floating-point determinant.

\subsection{Extremal function construction}
Given $A,S$ with $\#A=\#S+1=m+1$, form $E_{ij}=\omega^{\alpha_i\sigma_j}$ and compute a null vector of $E^{\mathsf T}$; cofactor expansion gives the closed form $f(\alpha_i)=(-1)^i\det E^{(i)}$, where $E^{(i)}$ deletes row $i$. Every such $m\times m$ minor is nonzero by Theorem~\ref{thm:cheb}, so $f$ has full support $A$, in accordance with Theorem~\ref{thm:sharp}. Cost $O(m^3)$ by elimination.

\subsection{Combinatorial sparse decoder}
Given $y_s=\hf(s)$ for $s\in S$, $\#S=2k$, and the promise that $f$ is $k$-sparse: for each candidate support $A$ of size $k$, solve $\sum_{a\in A}f(a)\omega^{as}=y_s$ in least squares and accept when the residual vanishes. Theorem~\ref{thm:rect} makes each candidate solution unique and Theorem~\ref{thm:recovery} makes the accepted support unique. Complexity $O\big(\binom{p}{k}k^2\#S\big)$: exponential in $k$, but deterministic for \emph{every} measurement set. When $S$ is an arithmetic progression, the classical Prony/Berlekamp--Massey method recovers $f$ in $O(k^3+kp)$ operations.

\section{Discussion}

\subsection{Primality as the exact hypothesis}
For composite $M=de$ the subgroup indicator $f=\mathbf 1_{e\mathbb{Z}/M}$ has $\#\supp f=d$ and $\hf$ supported on the annihilator of order $e$, so $\#\supp f+\#\supp\hf=d+e\approx2\sqrt M$ when $d\approx e$; the multiplicative bound $de=M$ is attained exactly, and the additive bound fails badly. Subgroups are the obstruction, and primes have none. Exhaustive enumeration over indicator signals for $M\le12$ gives minimum support total $M+1$ exactly for the primes and $\min_{d\mid M,\,1<d<M}(d+M/d)$ for the composites, always realised by a subgroup indicator. The same indicator explains the failure of deterministic sparse recovery over composite moduli.

\subsection{Relation to other proofs}
Frenkel's argument is a deformation: the vanishing of a complex determinant is transported to a divisibility statement about the single integer $[X^{N}]P$. This is in the spirit of the polynomial method; note that the Combinatorial Nullstellensatz proof of Cauchy--Davenport is also of that type, whereas the route taken here passes through analysis, exposing the sumset bound as a statement about supports and hence as a consequence of an uncertainty principle.

\subsection{Noise and conditioning}
Theorem~\ref{thm:recovery} is exact-arithmetic. In floating point the relevant quantity is the size of $|\det F_p[A,B]|$ relative to the Hadamard scale $n^{n/2}$, not merely its nonvanishing; effective lower bounds are the natural stability question. Numerically, all $3431$ square minors of $F_7$ are nonsingular, the smallest determinant modulus being $\approx0.868$; for $M=8$, by contrast, $1396$ of the $12869$ square minors vanish.

\section{Future directions}

\begin{conjecture}[Exact singularity locus for composite moduli]
For every $M$ and all $A,B\subseteq\ZM$ with $\#A=\#B=n$, the submatrix $(\zeta_M^{ab})$ is singular if and only if there is a divisor $d\mid M$, $1<d<M$, and a coset decomposition of $A$ and $B$ witnessing a vanishing sum of $d$-th roots of unity. For $M$ prime the locus is empty, and for every composite $M$ a singular $2\times2$ minor exists, namely $A=\{0,M/d\}$, $B=\{0,d\}$.
\end{conjecture}

The heuristic is that the only obstruction to nonsingularity is the decomposition of the set of $M$-th roots of unity into subgroup orbits: vanishing sums of $M$-th roots of unity are generated by full sums over prime-order subgroups, and each relation should produce exactly one singular minor pattern.

Further problems: (i) \emph{effective Chebotarev} --- explicit lower bounds for $|\det F_p[A,B]|$ in terms of $p$ and $n$, which would give noise-stability for sparse recovery; (ii) \emph{higher-rank analogues} over $\mathbb{F}_p^d$, where subspaces play the role of subgroups and the additive bound must be replaced by a version restricted to sets in general position; (iii) a Fourier-analytic proof of \emph{Vosper's theorem} on the extremal configurations of Cauchy--Davenport, leveraging the rigidity of Theorem~\ref{thm:rigid}; (iv) a \emph{fast deterministic decoder} recovering $k$-sparse signals from an arbitrary set of $2k$ frequencies in time polynomial in $k$ and $\log p$.

\section{Conclusion}

Chebotarev's theorem expresses arithmetic rigidity: at prime order the roots of unity admit no unexpected linear relations, and no square block of the Fourier matrix collapses. We proved it by deformation to an integer polynomial, obtained the exact quantitative statement --- vanishing to order precisely $\binom{n}{2}$ with leading coefficient prime to $p$ --- and showed that primality is necessary as well as sufficient. Its consequences form a chain of increasing concreteness: a sharp additive uncertainty principle with rigid extremisers; an exact identifiability threshold of $2k$ measurements for $k$-sparse signals under arbitrary measurement patterns; and the Cauchy--Davenport inequality obtained by convolving two extremal functions. Arithmetic rigidity, analytic uncertainty and combinatorial expansion are three faces of one fact, and the fact holds precisely at the primes.

